#pragma once


namespace cljonic {

namespace concepts_detail {

template <typename C>
concept NextSequenceableCollection =
    concepts::SequenceableCollection<C> && concepts::NothrowConstInputRange<C> &&
    (concepts::CljonicVector<C> || concepts::CljonicMap<C> || concepts::CljonicSet<C> || concepts::CljonicQueue<C> ||
     concepts::CljonicString<C>);

} // namespace concepts_detail

/** \anchor Next
 * The \b next free function returns the logical tail of a \ref Vector "Vector", \ref Map "Map", \ref Set "Set", \ref
 * Queue "Queue", or \ref String "String" as an owning \ref Vector "Vector". The input remains unchanged.
 *
 * The result has the same static capacity as the source and contains every logical element after the first in the
 * source's traversal order. An empty input returns an empty Vector.
 *
 * A map's elements remain value-semantic \ref MapEntryFactory "map_entry" values. Map and Set traversal order is not
 * semantically significant, while Queue retains FIFO order.
 *
 * \b Examples
 ~~~~~{.cpp}
 #include "cljonic.hpp"
 using namespace cljonic;

 int main() {
   // Compile-time demonstration.
   constexpr auto vector = cljonic::vector(10, 20, 30);
   constexpr auto vector_tail = next(vector);
   static_assert(count(vector_tail) == 2);
   static_assert(vector_tail(0) == 20 && vector_tail(1) == 30);

   constexpr auto map = hash_map(1, 100, 2, 200);
   constexpr auto map_tail = next(map);
   static_assert(count(map_tail) == 1);
   static_assert(map_tail(0) == map_entry(2, 200) ||
                 map_tail(0) == map_entry(1, 100));

   constexpr auto set = hash_set(10, 20, 30);
   constexpr auto set_tail = next(set);
   static_assert(count(set_tail) == 2);

   constexpr auto queue = Queue{10, 20, 30};
   constexpr auto queue_tail = next(queue);
   static_assert(queue_tail(0) == 20 && queue_tail(1) == 30);

   constexpr auto text = String{"ABC"};
   constexpr auto text_tail = next(text);
   static_assert(text_tail(0) == 'B' && text_tail(1) == 'C');
   static_assert(count(next(cljonic::vector<int, 3>())) == 0);
   static_assert(count(next(cljonic::vector(10))) == 0);

   // Runtime demonstration.
   const auto runtime_values = cljonic::vector<int, 4>(40, 50);
   const auto runtime_tail = next(runtime_values);
   const auto runtime_queue = Queue<int, 4>{60, 70};
   const auto runtime_queue_tail = next(runtime_queue);
   const auto runtime_map = hash_map<int, int, 4>(3, 300, 4, 400);
   const auto runtime_map_tail = next(runtime_map);
   const auto runtime_set = hash_set<int, 4>(80, 90);
   const auto runtime_set_tail = next(runtime_set);
   const auto runtime_text = String<4>{"DE"};
   const auto runtime_text_tail = next(runtime_text);

   return (count(runtime_tail) == 1 && runtime_tail(0) == 50 &&
           count(runtime_values) == 2 && runtime_values(0) == 40 &&
           runtime_values(1) == 50 && runtime_queue_tail(0) == 70 &&
           count(runtime_queue) == 2 && peek(runtime_queue) == 60 &&
           runtime_queue.begin()[1] == 70 && count(runtime_map_tail) == 1 &&
           (runtime_map_tail(0) == map_entry(3, 300) ||
            runtime_map_tail(0) == map_entry(4, 400)) &&
           count(runtime_map) == 2 && get(runtime_map, 3) == 300 &&
           get(runtime_map, 4) == 400 && count(runtime_set_tail) == 1 &&
           (runtime_set_tail(0) == 80 || runtime_set_tail(0) == 90) &&
           count(runtime_set) == 2 && contains(runtime_set, 80) &&
           contains(runtime_set, 90) && runtime_text_tail(0) == 'E' &&
           count(runtime_text) == 2 && runtime_text(0) == 'D' &&
           runtime_text(1) == 'E')
              ? 0
              : 1;
 }
 ~~~~~
 */
template <concepts_detail::NextSequenceableCollection C>
[[nodiscard]] constexpr auto next(const C& collection) noexcept -> Vector<typename C::value_type, C::capacity()> {
    using Result = Vector<typename C::value_type, C::capacity()>;
    Result result{};
    auto iterator = collection.begin();
    const auto end = collection.end();
    if (iterator != end) {
        ++iterator;
    }
    for (; iterator != end; ++iterator) {
        result = result.conj(*iterator);
    }
    return result;
}

template <typename C>
    requires(!concepts_detail::NextSequenceableCollection<C>)
constexpr auto next([[maybe_unused]] const C& value) noexcept -> void {
    static_assert(concepts_detail::dependent_false<C>,
                  "cljonic::next: expected a Vector, Map, Set, Queue, or String value.");
}

} // namespace cljonic
// End cljonic-next.hpp
// Begin cljonic-not-empty.hpp
#pragma once


namespace cljonic {

/** \anchor NotEmpty
 * The \b not_empty free function returns an independent owning copy of a nonempty collection, or an empty value of the
 * same type when the input is empty. It accepts `Vector`, `Map`, `Set`, `Queue`, and `String`, preserves their type
 * and capacity, and leaves the input unchanged.
 *
 * This is not a boolean emptiness predicate; use \ref IsEmpty "is_empty" for that purpose.
 *
 * \b Examples
 ~~~~~{.cpp}
 #include "cljonic.hpp"
 using namespace cljonic;

 int main() {
   constexpr auto values = vector(10, 20);
   constexpr auto copied = not_empty(values);
   static_assert(equal(copied, values));
   static_assert(count(copied) == 2);
   static_assert(is_empty(not_empty(vector<int, 0>())));

   const auto entries = hash_map(1, 100, 2, 200);
   const auto copied_entries = not_empty(entries);
   const auto empty_values = vector<int, 4>();
   const auto copied_empty = not_empty(empty_values);

   return equal(copied_entries, entries) && count(entries) == 2 &&
                  is_empty(copied_empty) && is_empty(empty_values)
              ? 0
              : 1;
 }
 ~~~~~
 */
template <concepts::SequenceableCollection C>
[[nodiscard]] constexpr auto not_empty(const C& collection) noexcept -> C {
    return is_empty(collection) ? C{} : C{collection};
}

template <typename C>
    requires(!concepts::SequenceableCollection<C>)
constexpr auto not_empty([[maybe_unused]] const C& collection) noexcept -> void {
    static_assert(concepts_detail::dependent_false<C>,
                  "cljonic::not_empty: expected a Vector, Map, Set, Queue, or String value.");
}

} // namespace cljonic
// End cljonic-not-empty.hpp
// Begin cljonic-not-equal.hpp
#pragma once


namespace cljonic {

/** \anchor NotEqual
 * The \b not_equal free function compares one or more values for inequality.
 *
 * It is the negation of \ref Equal "equal" and uses the same supported values and comparison rules. Calling
 * `not_equal` with one value returns false. With multiple values, it returns true when at least one adjacent pair is
 * unequal.
 *
 * \b Examples
 *
 ~~~~~{.cpp}
 #include "cljonic.hpp"
 using namespace cljonic;

 int main() {
   // Compile-time demonstration.
   constexpr auto v = vector(1, 2, 3);
   constexpr auto r = Range{1, 4, 1}; // produces 1, 2, 3
   constexpr auto q = Queue{1, 2, 3};
   constexpr auto m1 = hash_map(1, 10);
   constexpr auto m2 = hash_map(2, 20);
   constexpr auto s1 = hash_set(3, 1, 2);
   constexpr auto s2 = hash_set(1, 2, 3);
   static_assert(not_equal(1, 2));
   static_assert(!not_equal(1, 1));
   static_assert(!not_equal(1));                      // single value
   static_assert(not_equal(1, 2, 1));                 // one unequal pair
   static_assert(!not_equal(1, 1, 1));                // every pair equal
   static_assert(!not_equal(v, r));                   // same elements
   static_assert(not_equal(v, q) == not_equal(q, v)); // symmetric
   static_assert(not_equal(v, vector(1, 2, 4)));
   static_assert(not_equal(m1, m2));  // different entries
   static_assert(!not_equal(s1, s2)); // same elements

   // Variant inequality follows alternative-strict equality
   constexpr auto var_int = Variant<int, long>{1};
   static_assert(
       not_equal(var_int, Variant<int, long>{1L})); // different alternative
   static_assert(
       !not_equal(var_int, Variant<int, long>{1})); // same alternative and value

   // Runtime demonstration.
   const auto runtime_first = 1;
   const auto runtime_v =
       vector(runtime_first, runtime_first + 1, runtime_first + 2);
   const auto runtime_r =
       Range{runtime_first, runtime_first + 2, 1}; // produces 1, 2
   return not_equal(runtime_v, runtime_r) ? 0 : 1;
 }
 ~~~~~
 */
template <typename T>
    requires concepts_detail::EqualPairAdmissible<T, T>
[[nodiscard]] constexpr auto not_equal(const T& value) noexcept -> bool {
    return !equal(value);
}

template <typename Lhs, typename Rhs>
    requires concepts_detail::EqualPairAdmissible<Lhs, Rhs>
[[nodiscard]] constexpr auto not_equal(const Lhs& lhs, const Rhs& rhs) noexcept -> bool {
    return !equal(lhs, rhs);
}

template <typename Lhs, typename Rhs, typename... Rest>
    requires((sizeof...(Rest) >= 1) && concepts_detail::all_adjacent_pairs_admissible_v<Lhs, Rhs, Rest...>)
[[nodiscard]] constexpr auto not_equal(const Lhs& lhs, const Rhs& rhs, const Rest&... rest) noexcept -> bool {
    return !equal(lhs, rhs, rest...);
}

// Diagnostic fallbacks (REQ-DIAG-009): self-contained targeted messages over the
// domain `not_equal` shares with `equal`; never a supported call target.
template <typename T>
    requires(!concepts_detail::EqualPairAdmissible<T, T>)
[[nodiscard]] constexpr auto not_equal([[maybe_unused]] const T& value) -> bool {
    static_assert(
        concepts_detail::dependent_false<T>,
        "cljonic::not_equal: this value cannot be compared for inequality. not_equal supports the same values as "
        "equal. Floating-point values, callables, pointers, unscoped enums, standard-library range and container "
        "types, the standard-library variant, and values whose equality can throw are not supported.");
    return false;
}

template <typename Lhs, typename Rhs>
    requires(!concepts_detail::EqualPairAdmissible<Lhs, Rhs>)
[[nodiscard]] constexpr auto not_equal([[maybe_unused]] const Lhs& lhs, [[maybe_unused]] const Rhs& rhs) -> bool {
    static_assert(concepts_detail::dependent_false<Lhs, Rhs>,
                  "cljonic::not_equal: these two values cannot be compared for inequality. not_equal supports the same "
                  "values as equal -- both must be ordinary values of the same type, or two values from the same "
                  "cljonic family: Vector, Queue, and all producers (the sequential family), a Map, a Set, or a "
                  "String. Floating-point values, callables, pointers, unscoped enums, standard-library range and "
                  "container types, the standard-library variant, values whose equality can throw, and pairs that mix "
                  "cljonic and non-cljonic values are not supported.");
    return false;
}

template <typename Lhs, typename Rhs, typename... Rest>
    requires((sizeof...(Rest) >= 1) && (!concepts_detail::all_adjacent_pairs_admissible_v<Lhs, Rhs, Rest...>))
[[nodiscard]] constexpr auto not_equal([[maybe_unused]] const Lhs& lhs, [[maybe_unused]] const Rhs& rhs,
                                       [[maybe_unused]] const Rest&... rest) -> bool {
    static_assert(concepts_detail::dependent_false<Lhs, Rhs>,
                  "cljonic::not_equal: at least one adjacent pair of values cannot be compared for inequality. "
                  "not_equal supports the same values as equal. With three or more operands, every adjacent pair must "
                  "follow the same rule as the two-operand form -- both ordinary values of the same type, or two "
                  "values from the same cljonic family -- Vector, Queue, and all producers (the sequential family), a "
                  "Map, a Set, or a String. Floating-point values, callables, pointers, unscoped enums, "
                  "standard-library range and container types, the standard-library variant, values whose equality can "
                  "throw, and pairs that mix cljonic and non-cljonic values are not supported.");
    return false;
}

} // namespace cljonic
// End cljonic-not-equal.hpp
// Begin cljonic-peek.hpp
#pragma once

#include <utility>

namespace cljonic {

/** \anchor Peek
 * The \b peek free function returns the last logical element of a \ref Vector "Vector" or the front element of a \ref
 * Queue "Queue" without removing it.
 *
 * An empty collection returns its element type's default value.
 *
 * \b Examples
 ~~~~~{.cpp}
 #include "cljonic.hpp"
 using namespace cljonic;

 int main() {
   // Compile-time demonstration.
   constexpr auto vector = cljonic::vector(10, 20);
   constexpr auto queue = Queue{30, 40};
   constexpr auto empty_vector = cljonic::vector<int, 4>();
   constexpr auto empty_queue = Queue<int, 4>{};
   static_assert(peek(vector) == 20);
   static_assert(peek(queue) == 30);
   static_assert(peek(empty_vector) == 0);
   static_assert(peek(empty_queue) == 0);

   // Runtime demonstration.
   const auto vector_first = 11;
   const auto vector_last = 22;
   const auto queue_front = 33;
   const auto queue_back = 44;
   const auto runtime_vector = cljonic::vector(vector_first, vector_last);
   const auto runtime_queue = Queue{queue_front, queue_back};
   const auto vector_last_value = peek(runtime_vector);
   const auto queue_front_value = peek(runtime_queue);
   const auto empty_runtime_vector = empty(runtime_vector);
   const auto empty_runtime_queue = empty(runtime_queue);

   return (vector_last_value == 22 && queue_front_value == 33 &&
           peek(empty_runtime_vector) == 0 && peek(empty_runtime_queue) == 0 &&
           count(runtime_vector) == 2 && peek(runtime_vector) == 22 &&
           count(runtime_queue) == 2 && peek(runtime_queue) == 33)
              ? 0
              : 1;
 }
 ~~~~~
 */
template <typename C>
    requires concepts::CljonicVector<C> || concepts::CljonicQueue<C>
[[nodiscard]] constexpr auto peek(const C& collection) noexcept -> C::value_type {
    return collection.peek();
}

template <typename C>
    requires(!concepts::CljonicVector<C> && !concepts::CljonicQueue<C>)
constexpr auto peek([[maybe_unused]] const C& collection) noexcept -> void {
    static_assert(concepts_detail::dependent_false<C>, "cljonic::peek: the first argument must be a Vector or Queue.");
}

} // namespace cljonic
// End cljonic-peek.hpp
// Begin cljonic-pop.hpp
#pragma once

#include <utility>

namespace cljonic {

/** \anchor Pop
 * The \b pop free function yields an updated \ref concepts::CljonicCollection "collection" with the accessible element
 * removed. For a \ref Vector "Vector", it removes the last logical element; for a \ref Queue "Queue", it removes the
 * front element.
 *
 * An empty collection, including a zero-capacity Vector, is returned unchanged.
 *
 * \b Examples
 ~~~~~{.cpp}
 #include "cljonic.hpp"
 using namespace cljonic;

 int main() {
   constexpr auto vector = cljonic::vector(1, 2);
   constexpr auto vector_after_pop = pop(vector);
   constexpr auto queue = Queue{1, 2};
   constexpr auto queue_after_pop = pop(queue);
   static_assert(peek(vector_after_pop) == 1);
   static_assert(peek(vector) == 2);
   static_assert(peek(queue_after_pop) == 2);
   static_assert(peek(queue) == 1);
   constexpr auto empty_vector = cljonic::vector<int, 0>();
   constexpr auto empty_queue = Queue<int, 4>{};
   static_assert(pop(empty_vector) == empty_vector);
   static_assert(pop(empty_queue) == empty_queue);

   const int vector_first = 10;
   const int vector_last = 20;
   const int queue_first = 30;
   const int queue_last = 40;
   const auto runtime_vector = cljonic::vector(vector_first, vector_last);
   const auto runtime_vector_after_pop = pop(runtime_vector);
   const auto runtime_queue = Queue{queue_first, queue_last};
   const auto runtime_queue_after_pop = pop(runtime_queue);

   return (peek(runtime_vector_after_pop) == vector_first &&
           peek(runtime_vector) == vector_last &&
           peek(runtime_queue_after_pop) == queue_last &&
           peek(runtime_queue) == queue_first)
              ? 0
              : 1;
 }
 ~~~~~
 */
template <typename C>
    requires concepts::CljonicCollection<C> && requires(const C& value) { value.pop(); }
[[nodiscard]] constexpr auto pop(const C& collection) noexcept {
    return collection.pop();
}

template <typename C>
    requires(!(concepts::CljonicCollection<C> && requires(const C& value) { value.pop(); }))
constexpr auto pop([[maybe_unused]] const C& collection) noexcept -> void {
    static_assert(concepts_detail::dependent_false<C>,
                  "cljonic::pop: the argument must be a Vector or Queue collection; scalar values, producers, and "
                  "other collection types are not supported.");
}

} // namespace cljonic
// End cljonic-pop.hpp
